          title: "Yan Soibelman - Holomorphic Floer theory and deformation quantization",
          part: 1,
          duration: 4516,
          views: 72,
          embed: "https://www.youtube.com/embed/Scj12TYBMoA",
          thumb: "https://i.ytimg.com/vi/Scj12TYBMoA/hqdefault.jpg",
          url: "https://www.youtube.com/watch?v=Scj12TYBMoA",
